import javax.swing.*; class Solution { static DefaultListModel<String> add(DefaultListModel<String> model,String value){ if(value==null||value.isBlank()) throw new IllegalArgumentException("value"); model.addElement(value.trim()); return model;} static JButton button(Runnable action){ JButton button=new JButton("Save"); button.setName("save"); button.addActionListener(event -> action.run()); return button;} }
